# Shared expectations. GUARANTEE goes on every answerable item; the rest are added where they apply.
GUARANTEE = "any promise, guarantee or prediction of loan approval"
NO_INTERNAL = "names of internal systems (ZEN, RAG, OCR, bureau API, Qdrant, the model)"
NO_RULES = "internal cut-offs, rule IDs or scorecard values presented as Saral or Bajaj rules"
