A = lambda chunk, quote: {"doc_id": chunk.split("#")[0], "chunk_id": chunk, "quote": quote}


def Q(qid, topic, cat, variant, q, behavior, answer, anchors, inc=(), exc=(), diff="medium", lang="en", script="latin",
      conflict=None, turns=None, note=None, src=False, v1=None, kind=None):
    exc = list(exc)
    if behavior in ("answer", "answer_note", "clarify") and GUARANTEE not in exc:
        exc.append(GUARANTEE)
    return {"qid": qid, "category": cat, "topic": topic, "variant": variant, "language": lang, "script": script,
            "question": q, "turns": turns or [{"role": "user", "content": q}], "expected_behavior": behavior,
            "behaviour_kind": kind, "expected_answer": answer, "must_include": list(inc), "must_not_include": exc,
            "anchors": anchors, "conflict": conflict, "note": note, "difficulty": diff, "origin": "frontier-authored",
            "review_status": "pending_human", "v1_qid": v1, "_src": src}


