# ============================================================ KFS, APR, cooling-off
G += [
 Q("R2-KFS-01", "kfs_apr_cooling_off", "kfs", "direct", "What is a Key Facts Statement and when must the lender give it to me?", "answer",
   "A KFS is a short, standard sheet with the key facts of your loan in simple language. The lender must give it to you before you "
   "sign the loan contract, in a language you understand.",
   [A("RBI-RBC-NBFC-2025#038", "An NBFC shall provide a KFS to all prospective borrowers to help them take an informed view before executing the loan contract"),
    A("RBI-RBC-NBFC-2025#011", "Key Facts Statement (KFS) is a statement of key facts of a loan agreement, in simple and easier to understand language")],
   inc=["key facts in simple language", "before signing"], diff="easy", v1="SR-01"),
 Q("R2-KFS-02", "kfs_apr_cooling_off", "kfs_validity", "paraphrase", "How many days do I get to accept the terms in the KFS?", "answer",
   "At least 3 working days for loans of 7 days or longer (1 working day for shorter loans). If you agree within that time, the lender is bound by those terms.",
   [A("RBI-RBC-NBFC-2025#038", "shall have a validity period of at least three working days for loans having tenor of seven days or more"),
    A("RBI-RBC-NBFC-2025#039", "The NBFC shall be bound by the terms of the loan indicated in the KFS, if agreed to by the borrower during the validity period.")],
   inc=["at least 3 working days", "lender bound by the terms"], diff="medium", v1="SR-02"),
 Q("R2-KFS-03", "kfs_apr_cooling_off", "kfs_apr", "direct", "Does the KFS show the total cost including fees?", "answer",
   "Yes. It must include an APR calculation sheet and a repayment schedule, and the APR includes all charges the lender levies.",
   [A("RBI-RBC-NBFC-2025#039", "The KFS shall also include a computation sheet of Annual Percentage Rate (APR), and the amortisation schedule of the loan over the loan tenor. APR will include all charges which are levied by the NBFC.")],
   inc=["APR sheet", "repayment schedule", "all charges"], diff="easy", v1="SR-03"),
 Q("R2-KFS-04", "kfs_apr_cooling_off", "apr", "direct", "What does APR mean?", "answer",
   "APR is the yearly cost of your loan: the interest rate plus all the other charges.",
   [A("RBI-RBC-NBFC-2025#010", "Annual Percentage Rate (APR) means the annual cost of credit to the borrower which includes interest rate and all other charges associated with the credit facility.")],
   inc=["yearly cost", "interest plus charges"], diff="easy", v1="SR-04"),
 Q("R2-KFS-05", "kfs_apr_cooling_off", "cooling_off", "direct", "Is there a free-look or cooling-off period after I take a Bajaj loan?", "answer",
   "Yes. Bajaj's Citizen's Charter lists a cooling-off / free-look cancellation period of 1 day.",
   [A("BFL-CITIZENS-CHARTER-2025#012", "Cooling off / Free Look Cancellation period 1 Day")], inc=["1 day"], diff="easy", v1="SB-37"),
 Q("R2-KFS-06", "kfs_apr_cooling_off", "dl_cooling_off", "paraphrase", "I took a loan on an app and regret it already. Can I get out without a penalty?", "answer",
   "Yes, during the cooling-off period set by the lender (at least one day). You repay the principal and the proportionate APR, with no "
   "penalty; a reasonable one-time processing fee may be kept if the KFS disclosed it.",
   [A("RBI-NBFC-CF-2025#042", "The borrower shall be given an explicit option to exit a digital loan by paying the principal and the proportionate APR without any penalty during an initial “cooling-off period”."),
    A("RBI-NBFC-CF-2025#042", "subject to the period so determined not being less than one day"),
    A("RBI-NBFC-CF-2025#042", "An NBFC may retain a reasonable one-time processing fee, if the customer exits the loan during the cooling-off period.")],
   inc=["yes", "at least one day", "principal plus proportionate APR", "no penalty"], diff="medium", v1="SR-11"),
 Q("R2-KFS-07", "kfs_apr_cooling_off", "dl_cooling_off", "paraphrase", "If I cancel during the cooling-off period, do I get the processing fee back?", "answer",
   "Not necessarily. The lender may keep a reasonable one-time processing fee, but only if it was disclosed to you upfront in the KFS.",
   [A("RBI-NBFC-CF-2025#042", "(2) An NBFC may retain a reasonable one-time processing fee, if the customer exits the loan during the cooling-off period. This, if applicable, shall be disclosed to the customer upfront in KFS.")],
   inc=["may keep a reasonable one-time fee", "only if disclosed in KFS"], diff="medium",
   note="Phrasing modelled on RBI's digital-lending FAQ (Q16), seen only as a search excerpt; no source_url recorded."),
 Q("R2-KFS-08", "kfs_apr_cooling_off", "dl_cooling_off", "multi_hop",
   "The loan T&Cs say I can't cancel without the lender's approval and charges. Do I still have a cooling-off right on my app loan?", "answer_note",
   "For a digital loan, RBI's directions give you an explicit option to exit during the cooling-off period (at least one day) by "
   "repaying the principal and proportionate APR without penalty. Bajaj's Charter also lists a 1-day free-look period. Note: the "
   "detailed T&C clause you saw says cancellation needs the lender's approval and charges; that document has no 'updated as on' date.",
   [A("RBI-NBFC-CF-2025#042", "The borrower shall be given an explicit option to exit a digital loan by paying the principal and the proportionate APR without any penalty during an initial “cooling-off period”."),
    A("BFL-CITIZENS-CHARTER-2025#012", "Cooling off / Free Look Cancellation period 1 Day"),
    A("BFL-PL-DETAILED-TNC#023", "The Customer/s shall not be entitled to cancel the loan facility or refuse to accept disbursement of the loan facility, except with approval of BFL and payment to BFL of such cancellation or foreclosure charges as may be stipulated by BFL.")],
   inc=["RBI cooling-off exit for digital loans", "1-day free look", "T&C wording differs and is undated"],
   exc=["legal advice that the T&C clause is void"], diff="hard", conflict="C7"),
 Q("R2-KFS-09", "kfs_apr_cooling_off", "kfs_contents", "paraphrase", "Will the KFS tell me about recovery agents and who to complain to?", "answer",
   "Yes. Part 2 of the KFS covers the loan clause on recovery agents, the clause on grievance redressal, and the phone number and email of the nodal grievance officer.",
   [A("RBI-RBC-NBFC-2025#128", "Clause of Loan agreement relating to engagement of recovery agents Clause of Loan agreement which details grievance redressal mechanism Phone number and email id of the nodal grievance redressal officer")],
   inc=["recovery agents clause", "grievance redressal clause", "nodal officer contact"], diff="medium"),
 Q("R2-KFS-10", "kfs_apr_cooling_off", "kfs", "paraphrase", "Does the lender have to explain the KFS to me, or just hand it over?", "answer",
   "It must explain it. The KFS must be in a language you understand, its contents explained to you, and your acknowledgement taken that you understood it.",
   [A("RBI-RBC-NBFC-2025#038", "The KFS shall be written in a language understood by such borrowers. Contents of KFS shall be explained to the borrower and an acknowledgement shall be obtained that they have understood the same.")],
   inc=["explained", "language you understand", "acknowledgement"], diff="medium"),
 Q("R2-KFS-11", "kfs_apr_cooling_off", "apr", "multi_hop", "Two loans both say 12% interest. Why could one still cost me more?", "answer",
   "Because their fees can differ. Compare the APR, which adds the processing fee and other charges to the interest rate.",
   [A("BFL-PL-RATES-FEES#013", "Two personal loans with the same advertised interest rate may have different borrowing costs because their processing fees and other applicable charges differ."),
    A("BFL-PL-RATES-FEES#010", "The annual percentage rate (APR) adds the processing fee and other charges to the rate.")],
   inc=["fees differ", "compare APR"], exc=[OTHER_LENDER], diff="medium"),
]

# ============================================================ penal charges
G += [
 Q("R2-PEN-01", "penal_charges", "fees_penal", "direct", "What penalty is charged if I pay an EMI late?", "answer",
   "A penal charge of up to 36% a year on the late instalment, from the due date until it is fully paid.",
   [A("BFL-PL-RATES-FEES#002", "Delay in payment of instalment(s) shall attract Penal Charge at the rate of up to 36% per annum per instalment")],
   inc=["up to 36% a year", "until paid"], diff="easy", v1="SB-12"),
 Q("R2-PEN-02", "penal_charges", "penal_interest", "paraphrase", "Can an NBFC add penal interest to my interest rate if I miss an EMI?", "answer",
   "No. A penalty must be a separate 'penal charge', not extra interest added to your rate, and no interest can be charged on penal charges.",
   [A("RBI-RBC-NBFC-2025#044", "shall not be levied in the form of ‘penal interest’ that is added to the rate of interest charged on the advances."),
    A("RBI-RBC-NBFC-2025#044", "There shall be no capitalisation of penal charges, i.e., no further interest computed on such charges.")],
   inc=["no", "penal charge not penal interest"], diff="easy", v1="SR-05"),
 Q("R2-PEN-03", "penal_charges", "penal_disclosure", "direct", "Must the lender tell me the penal charges upfront?", "answer",
   "Yes. The amount and reason for penal charges must be shown upfront in the loan agreement and KFS, and on the lender's website.",
   [A("RBI-RBC-NBFC-2025#047", "The quantum and reason for penal charges shall be clearly disclosed by the NBFC to the customers upfront in the loan agreement and Most Important Terms & Conditions/ Key Fact Statement as applicable, in addition to being displayed on the NBFC’s website under Interest rates and Service Charges.")],
   inc=["yes", "loan agreement and KFS"], diff="easy", v1="SR-06"),
 Q("R2-PEN-04", "penal_charges", "penal_capitalisation", "paraphrase", "Will they charge interest on top of my late-payment penalty?", "answer",
   "No. Penal charges can't be capitalised, so no further interest is charged on them. Normal interest at your loan rate can still run on the unpaid EMI.",
   [A("RBI-RBC-NBFC-2025#044", "There shall be no capitalisation of penal charges, i.e., no further interest computed on such charges."),
    A("RBI-RBC-NBFC-2025#044", "the NBFC may charge interest on unpaid interest (including on unpaid EMI) at the contracted rate of interest till the date of remediation, and not at the penal rate of interest.")],
   inc=["no interest on penal charges", "contract-rate interest on unpaid EMI allowed"], diff="medium"),
 Q("R2-PEN-05", "penal_charges", "fees_penal", "multi_hop", "I paid one EMI ten days late. What exactly can Bajaj charge me?", "answer",
   "A penal charge of up to 36% a year on that instalment for the days it was late, and a bounce charge of Rs. 700 to Rs. 1,200 if the "
   "payment had failed. Under RBI rules penal charges apply only to the amount in default and can't be added to your interest rate.",
   [A("BFL-PL-RATES-FEES#002", "Penal Charge at the rate of up to 36% per annum per instalment from the respective due date until the date of receipt of the full instalment(s) amount."),
    A("BFL-PL-RATES-FEES#001", "Bounce charges Rs. 700 to Rs. 1,200/- per bounce"),
    A("RBI-RBC-NBFC-2025#045", "Such penal charges shall be reasonable and levied by the lenders only on the amount under default in a non-discriminatory manner")],
   inc=["up to 36% a year on the late instalment", "bounce charge if payment failed", "only on amount in default"], exc=[C5_BAD],
   diff="hard", conflict="C5"),
 Q("R2-PEN-06", "penal_charges", "penal_reminders", "paraphrase", "When they send me a payment reminder, should it mention the penalty?", "answer",
   "Yes. Reminders must state the applicable penal charges, and each time a penal charge is levied you must be told the amount and the reason.",
   [A("RBI-RBC-NBFC-2025#047", "Whenever reminders for non-compliance of material terms and conditions of loan are sent to borrowers, the applicable penal charges shall be communicated. Further, any instance of levy of penal charges and the reason thereof shall also be communicated.")],
   inc=["yes", "reason communicated"], diff="medium"),
 Q("R2-PEN-07", "penal_charges", "penal_disclosure", "multi_hop", "Where in my loan agreement should the late-payment penalty be written?", "answer",
   "In bold. RBI requires late-payment penalties to be mentioned in bold in the loan agreement, and Bajaj's Fair Practice Code says the same.",
   [A("RBI-RBC-NBFC-2025#022", "an NBFC shall mention the penalties charged for late repayment in bold in the loan agreement."),
    A("BFL-FPC-2026#005", "The Company will mention the penal charge which will be charged for late repayment and / or any other default on the part of the customer, in bold in the loan agreement.")],
   inc=["in bold"], diff="easy"),
]

