def load_corpus_meta():
    manifest = json.loads((ROOT / "data/corpus_v3/manifest.json").read_text(encoding="utf-8"))
    urls = {d["document_id"]: d.get("source_url") for d in manifest["documents"]}
    index = {}
    with (ROOT / "data/corpus_v3/chunk_index.csv").open(encoding="utf-8") as f:
        for row in csv.DictReader(f):
            index[row["chunk_id"]] = row
    return urls, index


def build(chunks_dir=None, out=OUT):
    urls, index = load_corpus_meta()
    chunks = {}
    if chunks_dir:
        for col in (N, R):
            for line in (Path(chunks_dir) / f"{col}.chunks.jsonl").open(encoding="utf-8"):
                c = json.loads(line)
                chunks[c["chunk_id"]] = c
    bad, ids, items = [], set(), []
    for g in G:
        g = dict(g)
        assert g["qid"] not in ids, g["qid"]
        ids.add(g["qid"])
        for an in g["anchors"]:
            row = index.get(an["chunk_id"])
            if row is None:
                bad.append((g["qid"], an["chunk_id"], "unknown chunk id"))
                continue
            an["collection"] = row["collection"]
            an["chunk_sha256"] = row["chunk_sha256"]
            if chunks and norm(an["quote"]) not in norm(chunks[an["chunk_id"]]["text"]):
                bad.append((g["qid"], an["chunk_id"], "quote not verbatim"))
        cols = sorted({a["collection"] for a in g["anchors"]})
        g["collections"] = cols
        g["collection"] = g["anchors"][0]["collection"] if g["anchors"] else None
        g["gold_docs"] = sorted({a["doc_id"] for a in g["anchors"]})
        g["gold_chunks"] = sorted({a["chunk_id"] for a in g["anchors"]})
        g["conflict_note"] = CONFLICTS.get(g["conflict"]) if g["conflict"] else None
        src = g.pop("_src")
        g["source_url"] = urls.get(g["anchors"][0]["doc_id"]) if (src and g["anchors"]) else None
        g["source_url_role"] = "phrasing modelled on the public FAQ / question on this page" if g["source_url"] else None
        g["calibration"] = False
        g["split"] = None
        g["golden_version"] = GOLDEN_VERSION
        items.append(g)
    if bad:
        raise SystemExit(f"anchor problems: {bad}")
    Path(out).parent.mkdir(parents=True, exist_ok=True)
    Path(out).write_text("".join(json.dumps(g, ensure_ascii=False) + "\n" for g in items), encoding="utf-8")
    return items, bool(chunks)


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--chunks", help="dir with the G1 cleaned chunk files; enables the verbatim anchor check")
    ap.add_argument("--out", default=str(OUT))
    a = ap.parse_args(argv)
    items, verified = build(a.chunks, a.out)
    from collections import Counter
    print(len(items), "items;", dict(Counter(g["expected_behavior"] for g in items)), dict(Counter(g["language"] for g in items)),
          "verbatim anchors checked" if verified else "WARNING: chunk texts not given, verbatim check skipped")


if __name__ == "__main__":
    main()
